draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // bird flying
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 100, H/2 + Math.cos(t) * 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 100, H/2 + Math.cos(t) * 50 - 20);
  ctx.lineTo(W/2 + Math.sin(t) * 100, H/2 + Math.cos(t) * 50 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 100 - 20, H/2 + Math.cos(t) * 50);
  ctx.lineTo(W/2 + Math.sin(t) * 100 + 20, H/2 + Math.cos(t) * 50);
  ctx.stroke();

  // fish swimming
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t) * 150, H - 50 + Math.sin(t) * 20, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t) * 150, H - 50 + Math.sin(t) * 20);
  ctx.lineTo(W/2 + Math.cos(t) * 150 + Math.cos(t) * 30, H - 50 + Math.sin(t) * 20 + Math.sin(t) * 10);
  ctx.stroke();

  ctx.restore();
}
